router.post(
  "/proveedores/:id/ajustes",
  requierePermiso("proveedores_finanzas", "autorizar"),
  async (req, res, next): Promise<void> => {
    try {
      const params = RegistrarAjusteProveedorParams.safeParse(req.params);
      if (!params.success) {
        res.status(400).json({ error: "ID inválido." });
        return;
      }

      const [prov] = await db
        .select({ id: proveedoresTable.id, activo: proveedoresTable.activo })
        .from(proveedoresTable)
        .where(eq(proveedoresTable.id, params.data.id))
        .limit(1);
      if (!prov) {
        res.status(404).json({ error: "Proveedor no encontrado." });
        return;
      }
      if (!prov.activo) {
        res.status(400).json({ error: "El proveedor está inactivo." });
        return;
      }

      const { importe, notas } = req.body as {
        importe?: unknown;
        notas?: unknown;
      };

      if (typeof importe !== "number" || importe === 0) {
        res.status(400).json({ error: "El importe debe ser un número no cero." });
        return;
      }

      if (typeof notas !== "string" || notas.length < 10) {
        res.status(400).json({
          error: "Las notas deben tener al menos 10 caracteres.",
        });
        return;
      }

      const row = await db.transaction(async (tx) =>
        registrarAjuste(tx, {
          proveedorId: params.data.id,
          importe: importe as number,
          notas,
          usuarioId: req.auth!.user.id,
          ip: getRequestIp(req),
        }),
      );

      res.status(201).json({
        id: row.id,
        proveedorId: row.proveedorId,
        entradaId: row.entradaId ?? null,
        importe: row.importe,
        tipo: row.tipo,
        formaPago: row.formaPago ?? null,
        referencia: row.referencia ?? null,
        fecha: row.fecha.toISOString(),
        usuarioId: row.usuarioId,
        notas: row.notas ?? null,
        createdAt: row.createdAt.toISOString(),
      });
    } catch (e) {
      next(e);
    }
  },
);

router.post(
  "/proveedores/:id/pagos/:pagoId/reversar",
  requierePermiso("proveedores_finanzas", "autorizar"),
  async (req, res, next): Promise<void> => {
    try {
      const proveedorId = Number(req.params.id);
      const pagoId = Number(req.params.pagoId);
      const motivo = typeof req.body?.motivo === "string" ? req.body.motivo.trim() : "";
      if (!Number.isInteger(proveedorId) || !Number.isInteger(pagoId) || !motivo) {
        res.status(400).json({ error: "ID y motivo son obligatorios." }); return;
      }
      if (req.body.efectivoE12 !== undefined) {
        requireE12();
        const data = e12ReturnSchema.parse(req.body.efectivoE12);
        const result = await db.transaction(tx => returnE12(e12Repository(tx), e12Actor(req.auth!.user, getRequestIp(req)), {
          proveedorId, pagoId, motivo, ...data,
        }));
        res.status(201).json(ReversarPagoProveedorResponse.parse({ ...presentPagoProveedor(result.pago),
          ...(req.auth!.user.rol === "ADMIN" ? { efectivoE12: result.efectivoE12 } : {}) }));
        return;
      }
      const reverso = await db.transaction((tx) => reversarPago(tx, {
        proveedorId, pagoId, motivo, usuarioId: req.auth!.user.id, ip: getRequestIp(req),
      }));
      res.status(201).json(
        ReversarPagoProveedorResponse.parse(presentPagoProveedor(reverso)),
      );
    } catch (error) {
      if (error instanceof Error && error.message === "PAYMENT_NOT_FOUND") {
        res.status(404).json({ error: "Pago no encontrado." }); return;
      }
      if (error instanceof Error && error.message === "PAYMENT_ALREADY_REVERSED") {
        res.status(409).json({ error: "El pago ya fue revertido." }); return;
      }
      next(error);
    }
  },
);

router.get(
  "/proveedores/:id/compras/:compraId",
  requierePermiso("proveedores_finanzas", "ver"),
  async (req, res, next): Promise<void> => {
    try {
      const params = GetProveedorCompraDetalleParams.safeParse(req.params);
      if (!params.success) { res.status(400).json({ error: "ID inválido." }); return; }
      const { ubicacionId, scopeError } = resolveReadScope(req.auth!);
      if (scopeError) { res.status(403).json({ error: scopeError }); return; }
      const compra = await db.execute<any>(sql`
        SELECT pp.*, e.fecha AS fecha_recepcion
        FROM pagos_proveedor pp
        JOIN entradas e ON e.id=pp.entrada_id
        WHERE pp.entrada_id=${params.data.compraId}
          AND pp.proveedor_id=${params.data.id}
          AND pp.tipo='COMPRA'
          ${ubicacionId === undefined ? sql`` : sql`AND e.ubicacion_id=${ubicacionId}`}`);
      if (!compra.rows[0]) { res.status(404).json({ error: "Compra no encontrada." }); return; }
      const compraMovimientoId = Number(compra.rows[0].id);
      const apps = await db.execute<any>(sql`
        SELECT a.pago_proveedor_id,a.compra_proveedor_id,a.importe,
          p.entrada_id,e.folio,p.fecha,
          EXISTS(SELECT 1 FROM pagos_proveedor r
            WHERE r.tipo='REVERSO' AND r.movimiento_origen_id=a.pago_proveedor_id) AS revertido,
          (SELECT r.notas FROM pagos_proveedor r
            WHERE r.tipo='REVERSO' AND r.movimiento_origen_id=a.pago_proveedor_id
            LIMIT 1) AS "motivoReverso",
          (c.importe-COALESCE((SELECT SUM(x.importe) FROM aplicaciones_pago_proveedor x
            WHERE x.compra_proveedor_id=c.id AND NOT EXISTS (SELECT 1 FROM pagos_proveedor r
              WHERE r.tipo='REVERSO' AND r.movimiento_origen_id=x.pago_proveedor_id)),0))::text saldo
        FROM aplicaciones_pago_proveedor a JOIN pagos_proveedor p ON p.id=a.pago_proveedor_id
        JOIN pagos_proveedor c ON c.id=a.compra_proveedor_id LEFT JOIN entradas e ON e.id=c.entrada_id
        WHERE a.compra_proveedor_id=${compraMovimientoId} ORDER BY a.id`);
      res.json(GetProveedorCompraDetalleResponse.parse({ compra: presentPagoProveedor({
        ...compra.rows[0],
        fecha: compra.rows[0].fecha_recepcion,
      }), aplicaciones: apps.rows.map((a: any) => ({
        pagoProveedorId: Number(a.pago_proveedor_id), compraProveedorId: Number(a.compra_proveedor_id), importe: a.importe,
        saldoAntes: a.saldo, saldoDespues: a.saldo, entradaId: a.entrada_id, folio: a.folio,
         fecha: new Date(a.fecha).toISOString(), resultado: Number(a.saldo) === 0 ? "SALDADA" : "PARCIAL",
         revertido: Boolean(a.revertido), motivoReverso: a.motivoReverso ?? null,
      })) }));
    } catch (e) { next(e); }
  },
);

router.get(
  "/proveedores/:id/pagos/:pagoId",
  requierePermiso("proveedores_finanzas", "ver"),
  async (req, res, next): Promise<void> => {
    try {
      const params = GetProveedorPagoDetalleParams.safeParse(req.params);
      if (!params.success) { res.status(400).json({ error: "ID inválido." }); return; }
      const pago = await db.execute<any>(sql`
        SELECT p.*,
          EXISTS(SELECT 1 FROM pagos_proveedor r WHERE r.tipo='REVERSO' AND r.movimiento_origen_id=p.id) AS revertido,
          (SELECT r.id FROM pagos_proveedor r WHERE r.tipo='REVERSO' AND r.movimiento_origen_id=p.id LIMIT 1) AS "reversoMovimientoId",
          (SELECT r.notas FROM pagos_proveedor r WHERE r.tipo='REVERSO' AND r.movimiento_origen_id=p.id LIMIT 1) AS "motivoReverso"
        FROM pagos_proveedor p WHERE p.id=${params.data.pagoId} AND p.proveedor_id=${params.data.id} AND p.tipo='PAGO'`);
      if (!pago.rows[0]) { res.status(404).json({ error: "Pago no encontrado." }); return; }
      const apps = await db.execute<any>(sql`
        SELECT a.*,c.entrada_id,e.folio,e.fecha AS fecha_recepcion,
          (c.importe-COALESCE((SELECT SUM(x.importe) FROM aplicaciones_pago_proveedor x
            WHERE x.compra_proveedor_id=c.id AND NOT EXISTS (SELECT 1 FROM pagos_proveedor r
              WHERE r.tipo='REVERSO' AND r.movimiento_origen_id=x.pago_proveedor_id)),0))::text saldo
        FROM aplicaciones_pago_proveedor a JOIN pagos_proveedor c ON c.id=a.compra_proveedor_id
        LEFT JOIN entradas e ON e.id=c.entrada_id WHERE a.pago_proveedor_id=${params.data.pagoId} ORDER BY a.id`);
      const saldo = await db.execute<any>(sql`SELECT (CASE WHEN EXISTS (
        SELECT 1 FROM pagos_proveedor r WHERE r.tipo='REVERSO' AND r.movimiento_origen_id=${params.data.pagoId}
      ) THEN 0 ELSE -importe-COALESCE((SELECT SUM(a.importe) FROM aplicaciones_pago_proveedor a
        WHERE a.pago_proveedor_id=${params.data.pagoId} AND NOT EXISTS (
          SELECT 1 FROM pagos_proveedor r WHERE r.tipo='REVERSO'
            AND r.movimiento_origen_id=a.pago_proveedor_id)),0) END)::text saldo
        FROM pagos_proveedor WHERE id=${params.data.pagoId}`);
      const detailE12 = await readE12Detail(db, params.data.pagoId, req.auth!.user.rol);
      res.json(GetProveedorPagoDetalleResponse.parse({ pago: { ...presentPagoProveedor(pago.rows[0]), ...(detailE12 ? { efectivoE12: detailE12 } : {}) }, saldoDisponible: saldo.rows[0]?.saldo ?? "0.00",
        aplicaciones: apps.rows.map((a: any) => ({ pagoProveedorId: Number(a.pago_proveedor_id), compraProveedorId: Number(a.compra_proveedor_id), importe: a.importe,
          saldoAntes: a.saldo, saldoDespues: a.saldo, entradaId: a.entrada_id, folio: a.folio, fecha: new Date(a.fecha_recepcion).toISOString(),
          resultado: Number(a.saldo) === 0 ? "SALDADA" : "PARCIAL" })) }));
    } catch (e) { next(e); }
  },
);

