router.get(
  "/proveedores/:id/exportar",
  requierePermiso("proveedores_finanzas", "ver"),
  async (req, res, next): Promise<void> => {
    try {
      const params = ExportarProveedorXlsxParams.safeParse(req.params);
      if (!params.success) {
        res.status(400).json({ error: "ID inválido." });
        return;
      }

      const [prov] = await db
        .select()
        .from(proveedoresTable)
        .where(eq(proveedoresTable.id, params.data.id))
        .limit(1);
      if (!prov) {
        res.status(404).json({ error: "Proveedor no encontrado." });
        return;
      }

      const desde = parseMexicoDateQuery(req.query.desde, "start");
      const hasta = parseMexicoDateQuery(req.query.hasta, "end");
      if (desde === null || hasta === null) {
        res.status(400).json({
          error: "Las fechas deben usar el formato YYYY-MM-DD.",
        });
        return;
      }

      const { movimientos, saldoActual } = await estadoCuenta({
        proveedorId: params.data.id,
        desde,
        hasta,
      });

      const workbook = new ExcelJS.Workbook();
      workbook.creator = "Mariana Textil";
      workbook.created = new Date();

      const sheet = workbook.addWorksheet("Estado de Cuenta");
      sheet.addRow(["Proveedor:", prov.nombre]);
      sheet.addRow(["Generado:", new Date().toLocaleString("es-MX")]);
      if (desde) sheet.addRow(["Desde:", desde.toLocaleDateString("es-MX")]);
      if (hasta) sheet.addRow(["Hasta:", hasta.toLocaleDateString("es-MX")]);
      sheet.addRow([]);
      sheet.addRow([
        "Fecha",
        "Tipo",
        "Folio",
        "Importe",
        "Saldo Acumulado",
        "Forma de Pago",
        "Subtotal facturado",
        "IVA facturado",
        "Referencia",
        "Notas",
      ]);

      for (const m of movimientos) {
        sheet.addRow([
          new Date(m.fecha).toLocaleDateString("es-MX"),
          m.tipo,
          m.folio == null ? "" : String(m.folio),
          toExcelNumber(m.importe),
          toExcelNumber(m.saldoAcumulado),
          m.formaPago ?? "",
          m.desgloseIva ? toExcelNumber(m.desgloseIva.subtotal) : "",
          m.desgloseIva ? toExcelNumber(m.desgloseIva.iva) : "",
          m.referencia ?? "",
          m.notas ?? "",
        ]);
      }

      sheet.addRow([]);
      sheet.addRow(["Saldo actual:", toExcelNumber(saldoActual)]);
      sheet.getColumn(4).numFmt = EXCEL_NUMBER_FORMAT.money;
      sheet.getColumn(5).numFmt = EXCEL_NUMBER_FORMAT.money;
      sheet.getColumn(7).numFmt = EXCEL_NUMBER_FORMAT.money;
      sheet.getColumn(8).numFmt = EXCEL_NUMBER_FORMAT.money;
      sheet.getRow(sheet.rowCount).getCell(2).numFmt = EXCEL_NUMBER_FORMAT.money;
      const sourcesE12 = (await enrichE12Rows(db, movimientos, req.auth!.user.rol)).filter(row => row.efectivoE12);
      if (sourcesE12.length) {
        const sources = workbook.addWorksheet("Orígenes E12");
        sources.addRow(["Movimiento", "Pago original", "Tipo", "Total ledger", "Caja ledger", "Fondo ledger", "Naturaleza retorno", "Motivo desbloqueo"]);
        for (const row of sourcesE12) {
          const detail = row.efectivoE12!;
          const sign = row.tipo === "PAGO" ? -1 : 1;
          sources.addRow([row.id, detail.pagoProveedorId, row.tipo, toExcelNumber(row.importe),
            sign * toExcelNumber(detail.caja), sign * toExcelNumber(detail.fondo),
            row.tipo === "REVERSO" ? detail.retorno?.naturaleza ?? "" : "", detail.desbloqueoCaja?.motivo ?? ""]);
        }
        for (const index of [4, 5, 6]) sources.getColumn(index).numFmt = EXCEL_NUMBER_FORMAT.money;
      }

      const filename = `estado-cuenta-${prov.nombre.replace(/\s+/g, "-").toLowerCase()}.xlsx`;
      res.setHeader(
        "Content-Type",
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      );
      res.setHeader(
        "Content-Disposition",
        `attachment; filename="${filename}"`,
      );

      await workbook.xlsx.write(res);
      res.end();
    } catch (e) {
      next(e);
    }
  },
);

